/// The query encoding every SDK in the family shares: RFC 3986 unreserved plus
/// the sub-delimiters a URI component may carry literally. A space becomes
/// `%20` rather than `+`, because `+` is a literal plus in a URI query and only
/// means a space to a parser reading the component as an HTML form body.
fn encode_query_component(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.as_bytes() {
        match byte {
            b'A'..=b'Z'
            | b'a'..=b'z'
            | b'0'..=b'9'
            | b'-'
            | b'_'
            | b'.'
            | b'~'
            | b'!'
            | b'*'
            | b'\''
            | b'('
            | b')' => out.push(*byte as char),
            other => out.push_str(&format!("%{other:02X}")),
        }
    }
    out
}

