/// `scheme://authority` of an absolute URL.
fn origin(url: &str) -> &str {
    let start = url.find("://").map_or(0, |index| index + 3);
    url[start..]
        .find(['/', '?', '#'])
        .map_or(url, |end| &url[..start + end])
}

/// `location` resolved against the URL it was answered from.
fn resolve_location(url: &str, location: &str) -> String {
    if location.contains("://") {
        return location.to_string();
    }
    if let Some(rest) = location.strip_prefix("//") {
        let scheme = url.split("://").next().unwrap_or("http");
        return format!("{}://{}", scheme, rest);
    }
    let root = origin(url);
    if location.starts_with('/') {
        return format!("{}{}", root, location);
    }
    let path = url[root.len()..]
        .split(['?', '#'])
        .next()
        .unwrap_or_default();
    format!(
        "{}{}{}",
        root,
        &path[..path.rfind('/').map_or(0, |index| index + 1)],
        location
    )
}

